import{normalize,formatMoney,escapeHtml,loadContext,saveSales,saleSalary,saleRevenue,saleDate,inDateRange,startOfMonth,endOfMonth,initPageState,enableDialogBackdropClose,showFatal}from"./core.js";

const $=id=>document.getElementById(id);let ctx,from=startOfMonth(new Date),to=endOfMonth(new Date),query="",activeId=null,deleteArmed=false,deleteTimer;
const iso=d=>{const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10)};
const localDateTime=d=>{const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,16)};
function filtered(){const q=normalize(query);return ctx.sales.filter(s=>inDateRange(s,from,to)&&(!q||normalize(`${s.article} ${s.title} ${s.commCode}`).includes(q)))}
function activeRows(){return filtered().filter(s=>!s.returned)}
function render(){
  const rows=filtered(),valid=rows.filter(s=>!s.returned),t=valid.reduce((a,s)=>{a.salary+=saleSalary(s);a.revenue+=saleRevenue(s);a.qty+=Number(s.quantity);return a},{salary:0,revenue:0,qty:0});
  $("filteredSalary").textContent=formatMoney(t.salary);$("filteredRevenue").textContent=formatMoney(t.revenue);$("filteredQuantity").textContent=t.qty;$("filteredReturns").textContent=rows.filter(s=>s.returned).length;
  $("salesEmpty").hidden=!!rows.length;
  $("salesList").innerHTML=[...rows].sort((a,b)=>saleDate(b)-saleDate(a)).map(s=>`<button class="sale-row ${s.returned?"returned":""}" data-edit="${s.id}"><div class="sale-main"><strong>${escapeHtml(s.title)}</strong><span>${escapeHtml(s.article)} · ${escapeHtml(s.commCode)} · ${saleDate(s).toLocaleString("ru-RU",{dateStyle:"short",timeStyle:"short"})}</span></div><div class="sale-status">${s.returned?"Возврат":"Продано"}</div><div class="sale-value revenue"><span>Продажа</span><b>${formatMoney(saleRevenue(s))}</b></div><div class="sale-value units"><span>Количество</span><b>${s.quantity}</b></div><div class="sale-value salary"><span>Начислено</span><b>${s.returned?"—":"+"+formatMoney(saleSalary(s))}</b></div><span class="edit-mark">›</span></button>`).join("");
}
function openEdit(id){const s=ctx.sales.find(x=>x.id===id);if(!s)return;activeId=id;deleteArmed=false;clearTimeout(deleteTimer);$("deleteSale").textContent="Удалить";$("editTitle").textContent=s.title;$("editArticle").textContent=`Артикул ${s.article} · ${s.commCode}`;$("editDate").value=localDateTime(saleDate(s));$("editPrice").value=s.price;$("editQuantity").value=s.quantity;$("editStatus").value=s.returned?"returned":"sold";$("editError").textContent="";previewEdit();$("editDialog").showModal()}
function previewEdit(){const s=ctx?.sales.find(x=>x.id===activeId),returned=$("editStatus").value==="returned";$("editSalary").textContent=returned?"0 ₸":formatMoney(Number($("editPrice").value)*Number($("editQuantity").value)*(Number(s?.rate)||0))}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backupExport(){const payload={format:"seb-navigator-sales",version:1,exportedAt:new Date().toISOString(),sales:ctx.sales};saveBlob(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),`SEB-продажи-резерв-${iso(new Date)}.json`);$("exportStatus").textContent="Резервная копия сохранена."}
async function backupImport(file){const data=JSON.parse(await file.text());if(data?.format!=="seb-navigator-sales"||data.version!==1||!Array.isArray(data.sales))throw Error("Это не резервная копия SEB Navigator.");const cut=Date.now()-365*86400000,valid=data.sales.filter(s=>s&&s.id&&s.article&&Number(s.price)>0&&Number(s.quantity)>0&&saleDate(s).getTime()>=cut);if(!confirm(`Восстановить ${valid.length} продаж и заменить текущую историю?`))return;ctx.sales=valid;await saveSales(valid);render();$("exportStatus").textContent=`Восстановлено продаж: ${valid.length}.`}
function headerKey(v){return String(v??"").trim().toLowerCase().replaceAll("ё","е").replace(/\s+/g," ")}
function colLetters(ref){return String(ref||"").match(/[A-Z]+/)?.[0]||""}function colNumber(letters){let n=0;for(const c of letters)n=n*26+c.charCodeAt(0)-64;return n}
function cellValue(cell,shared){if(!cell)return"";const t=cell.getAttribute("t"),v=cell.getElementsByTagName("v")[0]?.textContent??"";if(t==="s")return shared[Number(v)]??"";if(t==="inlineStr")return[...cell.getElementsByTagName("t")].map(x=>x.textContent).join("");return v}
function setNumberCell(doc,row,col,rowNo,value){const ref=`${col}${rowNo}`;let cell=[...row.getElementsByTagName("c")].find(c=>c.getAttribute("r")===ref);if(!cell){cell=doc.createElementNS(row.namespaceURI,"c");cell.setAttribute("r",ref);const target=colNumber(col),next=[...row.children].find(c=>c.localName==="c"&&colNumber(colLetters(c.getAttribute("r")))>target);next?row.insertBefore(cell,next):row.appendChild(cell)}cell.removeAttribute("t");[...cell.children].filter(x=>["v","f","is"].includes(x.localName)).forEach(x=>x.remove());if(value>0){const v=doc.createElementNS(cell.namespaceURI,"v");v.textContent=String(value);cell.appendChild(v)}}
function escapeRegExp(v){return String(v).replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}
function patchQuantityCell(xml,ref,value){const safe=escapeRegExp(ref),paired=new RegExp(`(<c\\b(?=[^>]*\\br=["']${safe}["'])(?![^>]*\\/>)[^>]*>)[\\s\\S]*?(<\\/c>)`);if(paired.test(xml))return xml.replace(paired,`$1<v>${value}</v>$2`);const empty=new RegExp(`<c\\b([^>]*\\br=["']${safe}["'][^>]*)\\s*\\/>`);if(empty.test(xml))return xml.replace(empty,`<c$1><v>${value}</v></c>`);const rowNo=ref.match(/\d+$/)?.[0],row=new RegExp(`(<row\\b[^>]*\\br=["']${rowNo}["'][^>]*>[\\s\\S]*?)(<\\/row>)`);return xml.replace(row,`$1<c r="${ref}"><v>${value}</v></c>$2`)}
async function forceWorkbookRecalculation(zip){const workbookPath="xl/workbook.xml",workbookFile=zip.file(workbookPath);if(workbookFile){let xml=await workbookFile.async("text"),calc='<calcPr calcId="0" calcMode="auto" fullCalcOnLoad="1" forceFullCalc="1" refMode="R1C1"/>';xml=/<calcPr\b[^>]*\/>/.test(xml)?xml.replace(/<calcPr\b[^>]*\/>/,calc):xml.replace(/<extLst\b|<\/workbook>/,m=>calc+m);zip.file(workbookPath,xml)}zip.remove("xl/calcChain.xml");const relPath="xl/_rels/workbook.xml.rels",relFile=zip.file(relPath);if(relFile){let xml=await relFile.async("text");xml=xml.replace(/<Relationship\b[^>]*Type=["'][^"']*\/calcChain["'][^>]*\/>/g,"");zip.file(relPath,xml)}const typesPath="[Content_Types].xml",typesFile=zip.file(typesPath);if(typesFile){let xml=await typesFile.async("text");xml=xml.replace(/<Override\b[^>]*PartName=["']\/xl\/calcChain\.xml["'][^>]*\/>/g,"");zip.file(typesPath,xml)}}
async function exportReport(){const rows=activeRows();if(!rows.length)throw Error("За выбранный период нет активных продаж.");let buffer=ctx.dataset.rawWorkbook;if(!buffer)buffer=await fetch("./data/commission-template.xlsx").then(r=>r.arrayBuffer());const zip=await JSZip.loadAsync(buffer),parser=new DOMParser,shared=[];if(zip.file("xl/sharedStrings.xml")){const doc=parser.parseFromString(await zip.file("xl/sharedStrings.xml").async("text"),"application/xml");for(const si of doc.getElementsByTagName("si"))shared.push([...si.getElementsByTagName("t")].map(t=>t.textContent).join(""))}const relDoc=parser.parseFromString(await zip.file("xl/_rels/workbook.xml.rels").async("text"),"application/xml"),paths=[...relDoc.getElementsByTagName("Relationship")].filter(r=>r.getAttribute("Type")?.endsWith("/worksheet")).map(r=>{const t=r.getAttribute("Target");return t.startsWith("/")?t.slice(1):`xl/${t.replace(/^\.\//,"")}`}),qty=new Map;for(const s of rows)qty.set(normalize(s.commCode),(qty.get(normalize(s.commCode))||0)+Number(s.quantity));for(const path of paths){const file=zip.file(path);if(!file)continue;let xml=await file.async("text");const doc=parser.parseFromString(xml,"application/xml"),sheetRows=[...doc.getElementsByTagName("row")];let header=null,codeCol="",qtyCol="";for(const row of sheetRows.slice(0,20)){const cells=[...row.getElementsByTagName("c")],map=new Map(cells.map(c=>[headerKey(cellValue(c,shared)),colLetters(c.getAttribute("r"))]));if(map.has("comm.code")){header=Number(row.getAttribute("r"));codeCol=map.get("comm.code");qtyCol=[...map].find(([k])=>k==="количество")?.[1]||"";break}}if(!header||!qtyCol)continue;for(const row of sheetRows){const rn=Number(row.getAttribute("r"));if(rn<=header)continue;const codeCell=[...row.getElementsByTagName("c")].find(c=>colLetters(c.getAttribute("r"))===codeCol),code=normalize(cellValue(codeCell,shared)),value=qty.get(code)||0;if(code&&value>0)xml=patchQuantityCell(xml,`${qtyCol}${rn}`,value)}zip.file(path,xml)}return zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"})}
async function shareReport(){const b=$("exportButton"),status=$("exportStatus");b.disabled=true;status.textContent="Формирую точную копию отчёта…";try{const blob=await exportReport(),name=`SEB-продажи-${iso(from)}-${iso(to)}.xlsx`,file=new File([blob],name,{type:blob.type});if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:"Отчёт SEB",text:`Продажи ${iso(from)} — ${iso(to)}`});status.textContent="Отчёт передан в меню «Поделиться».";return}catch(e){if(e.name==="AbortError"){status.textContent="Отправка отменена.";return}}}saveBlob(blob,name);status.textContent="Системная отправка недоступна — отчёт скачан. Его можно отправить в Telegram или WhatsApp."}catch(e){status.textContent=e.message||"Не удалось сформировать отчёт."}finally{b.disabled=false}}
async function init(){
  initPageState("sales",()=>({from:iso(from),to:iso(to),query}),s=>{if(s.from)from=new Date(`${s.from}T00:00:00`);if(s.to)to=new Date(`${s.to}T23:59:59.999`);query=s.query||""});ctx=await loadContext();$("dateFrom").value=iso(from);$("dateTo").value=iso(to);$("salesSearch").value=query;render();
  const dates=()=>{from=new Date(`${$("dateFrom").value}T00:00:00`);to=new Date(`${$("dateTo").value}T23:59:59.999`);if(from>to)to=endOfMonth(from);$("dateTo").value=iso(to);render()};$("dateFrom").onchange=$("dateTo").onchange=dates;
  $("salesSearch").oninput=e=>{query=e.target.value;render()};$("salesList").onclick=e=>{const row=e.target.closest("[data-edit]");if(row)openEdit(row.dataset.edit)};
  $("closeEdit").onclick=()=>$("editDialog").close();$("editForm").oninput=previewEdit;$("editForm").onsubmit=async e=>{e.preventDefault();const s=ctx.sales.find(x=>x.id===activeId),price=Number($("editPrice").value),quantity=Number($("editQuantity").value),date=new Date($("editDate").value);if(!s||!(price>0)||!Number.isInteger(quantity)||quantity<1||Number.isNaN(date.getTime())){$("editError").textContent="Проверьте дату, цену и количество.";return}Object.assign(s,{price,quantity,soldAt:date.toISOString(),returned:$("editStatus").value==="returned",updatedAt:new Date().toISOString()});await saveSales(ctx.sales);$("editDialog").close();render()};
  $("deleteSale").onclick=async()=>{if(!deleteArmed){deleteArmed=true;$("deleteSale").textContent="Подтвердить удаление";deleteTimer=setTimeout(()=>{deleteArmed=false;$("deleteSale").textContent="Удалить"},5000);return}ctx.sales=ctx.sales.filter(s=>s.id!==activeId);await saveSales(ctx.sales);$("editDialog").close();render()};
  $("exportButton").onclick=shareReport;
  $("backupExport").onclick=backupExport;$("backupImport").onclick=()=>$("backupFile").click();$("backupFile").onchange=async()=>{const file=$("backupFile").files?.[0];if(!file)return;try{await backupImport(file)}catch(e){$("exportStatus").textContent=e.message}$("backupFile").value=""};
}
const generateWorkbook=JSZip.prototype.generateAsync;JSZip.prototype.generateAsync=async function(...args){await forceWorkbookRecalculation(this);return generateWorkbook.apply(this,args)};
enableDialogBackdropClose($("editDialog"));init().catch(showFatal);
